const items = $input.all();
if (items.length !== 1) throw new Error('one_envelope_required');
const item = items[0]; const v = item.json;
if (Object.keys(item.binary || {}).length) throw new Error('attachments_unsupported: no approved configured extractor; nothing written');
if (!Array.isArray(v.from?.value) || v.from.value.length !== 1) throw new Error('one_sender_required');
if (typeof v.text !== 'string') throw new Error('plain_text_required');
const raw = {version:1,messageId:v.messageId ?? null,from:v.from.value[0].address,subject:v.subject ?? '',body:v.text,autoSubmitted:v.headers?.['auto-submitted'] ?? '',precedence:v.headers?.precedence ?? '',attachments:[]};
function canonical(v) { if (v === null || ['string','boolean','number'].includes(typeof v)) return JSON.stringify(v); if (Array.isArray(v)) return '['+v.map(canonical).join(',')+']'; if (v && Object.getPrototypeOf(v) === Object.prototype) return '{'+Object.keys(v).sort().map(k=>JSON.stringify(k)+':'+canonical(v[k])).join(',')+'}'; throw new Error('invalid_envelope'); }
const json = canonical(raw); if (Buffer.byteLength(json) > 131072) throw new Error('input_too_large');
const payload = Buffer.from(json).toString('base64'); if (!/^[A-Za-z0-9+/]+={0,2}$/.test(payload)) throw new Error('invalid_transport');
return [{json:{payload}}];

const items = $input.all(); if (items.length !== 1) throw new Error('one_result_required'); const r = items[0].json;
if (r.code !== 0 || typeof r.stdout !== 'string' || r.stdout.length > 20000) throw new Error('runner_failed');
const v = JSON.parse(r.stdout);
if (!v || Object.keys(v).sort().join(',') !== 'reason,reply,requestId,status,version' || v.version !== 1 || !['approval_required','reply_ready','rejected','failed'].includes(v.status) || !(v.requestId === null || /^[a-f0-9]{64}$/.test(v.requestId)) || !(v.reason === null || typeof v.reason === 'string')) throw new Error('invalid_result');
if (v.status === 'reply_ready') { const e=v.reply; if (!v.requestId || !e || Object.keys(e).sort().join(',') !== 'body,subject,to' || typeof e.to !== 'string' || !/^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/.test(e.to) || typeof e.subject !== 'string' || !e.subject.length || /[\r\n\0]/.test(e.subject) || typeof e.body !== 'string' || !e.body.length || e.body.includes('\0') || e.body.length > 16384) throw new Error('invalid_reply'); } else if (v.reply !== null) throw new Error('unexpected_reply');
return [{json:v}];
